def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Parse one field starting at position i
        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    # Check if this is a doubled quote or the closing quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # Closing quote found
                        i += 1
                        # Must be followed by comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        if i < len(line):
                            i += 1  # Skip the comma
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field - runs until comma or end of line
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields

